/** void ShowContestEntryMonPic(void)
 *  Source : src/contest_util.c */
export function ShowContestEntryMonPic(rt: DecompRuntime): any {
  let palette: any = null;
      let personality, otId;
      let species = 0;
      let spriteId = 0;
      let taskId = 0;
      let left, top;

      if (FindTaskIdByFunc(Task_ShowContestEntryMonPic) == TASK_NONE)
      {
          AllocateMonSpritesGfx();
          left = 10;
          top = 3;
          species = gContestMons[gSpecialVar_0x8006].species;
          personality = gContestMons[gSpecialVar_0x8006].personality;
          otId = gContestMons[gSpecialVar_0x8006].otId;
          taskId = rt.CreateTask((t) => Task_ShowContestEntryMonPic(t, rt), 0x50);
          task.data[0] = 0;
          task.data[1] = species;
          if (gSpecialVar_0x8006 == gContestPlayerMonIndex)
              HandleLoadSpecialPokePic_2(gMonFrontPicTable[species], gMonSpritesGfxPtr.sprites.ptr[B_POSITION_OPPONENT_LEFT], species, personality);
          else
              HandleLoadSpecialPokePic_DontHandleDeoxys(gMonFrontPicTable[species], gMonSpritesGfxPtr.sprites.ptr[B_POSITION_OPPONENT_LEFT], species, personality);

          palette = GetMonSpritePalStructFromOtIdPersonality(species, otId, personality);
          LoadCompressedSpritePalette(palette);
          SetMultiuseSpriteTemplateToPokemon(species, B_POSITION_OPPONENT_LEFT);
          gMultiuseSpriteTemplate.paletteTag = palette.tag;
          spriteId = rt.CreateSpriteFromTemplate('gMultiuseSpriteTemplate',  (left + 1) * 8 + 32, (top * 8) + 40, 0);

          if (gLinkContestFlags & LINK_CONTEST_FLAG_IS_LINK)
          {
              if (!(gLinkContestFlags & LINK_CONTEST_FLAG_HAS_RS_PLAYER))
                  DoMonFrontSpriteAnimation(_gs(rt, spriteId), species, false, 0);
          }
          else
          {
              DoMonFrontSpriteAnimation(_gs(rt, spriteId), species, false, 0);
          }

          task.data[2] = spriteId;
          task.data[3] = left;
          task.data[4] = top;
          rt.setSpriteCallback(spriteId, SpriteCallbackDummy);
          rt.gba.oam[_gs(rt, spriteId).oamIndex].priority = 0;
      }
}

