/** void GenerateContestRand(void)
 *  Source : src/contest_util.c */
export function GenerateContestRand(rt: DecompRuntime): any {
  let random = 0;
      let result = 0;

      if (gLinkContestFlags & LINK_CONTEST_FLAG_IS_LINK)
      {
          gContestRngValue = ISO_RANDOMIZE1(gContestRngValue);
          random = gContestRngValue >> 16;
          result = gSpecialVar_Result;
      }
      else
      {
          result = gSpecialVar_Result;
          random = Math.floor(Math.random() * 0x10000);
      }
      result = random % result;
}

