/** void SetMewAboveGrass(void)
 *  Source : src/faraway_island.c */
export function SetMewAboveGrass(rt: DecompRuntime): any {
  let x = 0;
      let y = 0;
      let mew: any = gObjectEvents[GetMewObjectEventId()];

      mew.invisible = false;
      if (gSpecialVar_0x8004 == 1)
      {
           
          mew.fixedPriority = 1;
          _gs(rt, mew.spriteId).subspriteMode = SUBSPRITES_IGNORE_PRIORITY;
          _gs(rt, mew.spriteId).subpriority = 1;
      }
      else
      {
           
           
          VarSet(VAR_FARAWAY_ISLAND_STEP_COUNTER, 0xFFFF);
          mew.fixedPriority = 1;
          _gs(rt, mew.spriteId).subspriteMode = SUBSPRITES_IGNORE_PRIORITY;
          if (gSpecialVar_Facing != DIR_NORTH)
              _gs(rt, mew.spriteId).subpriority = 1;

          LoadSpritePalette(gSpritePalette_GeneralFieldEffect1);
          UpdateSpritePaletteWithWeather(IndexOfSpritePaletteTag(gSpritePalette_GeneralFieldEffect1.tag));

          x = mew.currentCoords.x;
          y = mew.currentCoords.y;
          SetSpritePosToOffsetMapCoords(x, y, 8, 8);
          sGrassSpriteId = CreateSpriteAtEnd(gFieldEffectObjectTemplatePointers[FLDEFFOBJ_LONG_GRASS], x, y, _gs(rt, mew.spriteId).subpriority - 1);
          if (sGrassSpriteId != MAX_SPRITES)
          {
              let sprite: any = _gs(rt, sGrassSpriteId);
              sprite.coordOffsetEnabled = 1;
              rt.gba.oam[sprite.oamIndex].priority = 2;
              sprite.callback = SpriteCallbackDummy;
          }
      }
}

