/** u16 GetSlotMachineId(void)
 *  Source : src/field_specials.c */
export function GetSlotMachineId(rt: DecompRuntime): any {
  const sSlotMachineRandomSeeds: any = [12, 2, 4, 5, 1, 8, 7, 11, 3, 10, 9, 6];
      const sSlotMachineIds: any = [
          SLOT_MACHINE_UNLUCKIEST,
          SLOT_MACHINE_UNLUCKIER,
          SLOT_MACHINE_UNLUCKIER,
          SLOT_MACHINE_UNLUCKY,
          SLOT_MACHINE_UNLUCKY,
          SLOT_MACHINE_UNLUCKY,
          SLOT_MACHINE_LUCKY,
          SLOT_MACHINE_LUCKY,
          SLOT_MACHINE_LUCKY,
          SLOT_MACHINE_LUCKIER,
          SLOT_MACHINE_LUCKIER,
          SLOT_MACHINE_LUCKIEST
      ];
      const sSlotMachineServiceDayIds: any = [
          SLOT_MACHINE_LUCKY,
          SLOT_MACHINE_LUCKY,
          SLOT_MACHINE_LUCKY,
          SLOT_MACHINE_LUCKY,
          SLOT_MACHINE_LUCKY,
          SLOT_MACHINE_LUCKY,
          SLOT_MACHINE_LUCKIER,
          SLOT_MACHINE_LUCKIER,
          SLOT_MACHINE_LUCKIER,
          SLOT_MACHINE_LUCKIER,
          SLOT_MACHINE_LUCKIEST,
          SLOT_MACHINE_LUCKIEST
      ];

      let rnd = gSaveBlock1Ptr.dewfordTrends[0].trendiness + gSaveBlock1Ptr.dewfordTrends[0].rand + sSlotMachineRandomSeeds[gSpecialVar_0x8004];
      if (IsPokeNewsActive(POKENEWS_GAME_CORNER))
          return sSlotMachineServiceDayIds[rnd % SLOT_MACHINE_COUNT];

      return sSlotMachineIds[rnd % SLOT_MACHINE_COUNT];
}

