/** void PickLotteryCornerTicket(void)
 *  Source : src/lottery_corner.c */
export function PickLotteryCornerTicket(rt: DecompRuntime): any {
  let i = 0;
      let j = 0;
      let box = 0;
      let slot = 0;

      gSpecialVar_0x8004 = 0;
      slot = 0;
      box = 0;
      for (i = 0; i < PARTY_SIZE; i++)
      {
          let mon: any = gPlayerParty[i];

          if (GetMonData(mon, MON_DATA_SPECIES) != SPECIES_NONE)
          {
               
              if (!GetMonData(mon, MON_DATA_IS_EGG))
              {
                  let otId = GetMonData(mon, MON_DATA_OT_ID);
                  let numMatchingDigits = GetMatchingDigits(gSpecialVar_Result, otId);

                  if (numMatchingDigits > gSpecialVar_0x8004 && numMatchingDigits > 1)
                  {
                      gSpecialVar_0x8004 = numMatchingDigits - 1;
                      box = TOTAL_BOXES_COUNT;
                      slot = i;
                  }
              }
          }
          else  
          {
              break;
          }
      }

      for (i = 0; i < TOTAL_BOXES_COUNT; i++)
      {
          for (j = 0; j < IN_BOX_COUNT; j++)
          {
              if (GetBoxMonData(gPokemonStoragePtr.boxes[i][j], MON_DATA_SPECIES) != SPECIES_NONE &&
              !GetBoxMonData(gPokemonStoragePtr.boxes[i][j], MON_DATA_IS_EGG))
              {
                  let otId = GetBoxMonData(gPokemonStoragePtr.boxes[i][j], MON_DATA_OT_ID);
                  let numMatchingDigits = GetMatchingDigits(gSpecialVar_Result, otId);

                  if (numMatchingDigits > gSpecialVar_0x8004 && numMatchingDigits > 1)
                  {
                      gSpecialVar_0x8004 = numMatchingDigits - 1;
                      box = i;
                      slot = j;
                  }
              }
          }
      }

      if (gSpecialVar_0x8004 != 0)
      {
          gSpecialVar_0x8005 = sLotteryPrizes[gSpecialVar_0x8004 - 1];

          if (box == TOTAL_BOXES_COUNT)
          {
              gSpecialVar_0x8006 = 0;
              GetMonData(gPlayerParty[slot], MON_DATA_NICKNAME, gStringVar1);
          }
          else
          {
              gSpecialVar_0x8006 = 1;
              GetBoxMonData(gPokemonStoragePtr.boxes[box][slot], MON_DATA_NICKNAME, gStringVar1);
          }
          StringGet_Nickname(gStringVar1);
      }
}

