/** void SetMirageTowerVisibility(void)
 *  Source : src/mirage_tower.c */
export function SetMirageTowerVisibility(rt: DecompRuntime): any {
  let rand = 0;
      let visible = 0;

      if (VarGet(VAR_MIRAGE_TOWER_STATE))
      {
           
          FlagClear(FLAG_MIRAGE_TOWER_VISIBLE);
          return;
      }

      rand = Math.floor(Math.random() * 0x10000);
      visible = rand & 1;
      if (FlagGet(FLAG_FORCE_MIRAGE_TOWER_VISIBLE) == true)
          visible = true;

      if (visible)
      {
          FlagSet(FLAG_MIRAGE_TOWER_VISIBLE);
          TryStartMirageTowerPulseBlendEffect();
          return;
      }

      FlagClear(FLAG_MIRAGE_TOWER_VISIBLE);
}

